-- Boshiamy prefix completion, ordered by common-character frequency.
--
-- Rime's built-in enable_completion orders candidates by remaining code
-- length first: for `i`, every two-code character (應, 応, 讀, 鞏, 誤, 工)
-- comes before the three-code ones (這, 電, 請, 記).  That is not "common
-- characters first".
--
-- boshiamy_completion_data.lua is generated by tools/make_hints.py from
-- data/essay.txt: each prefix maps to its unique characters sorted by
-- frequency.  Exact-code characters are excluded because the main table
-- translator already provides them in table order.
--
-- Candidate quality 0 sits between the main table (exp(weight) = inf) and
-- the English raw candidate (-1000000), so the menu order is:
--   exact code -> frequency-ordered completions -> English raw.

local index = require("boshiamy_completion_data")

local function translator(input, seg, env)
  if not seg:has_tag("abc") then
    return
  end
  local chars = index[input]
  if not chars or chars == "" then
    return
  end

  for text, code in chars:gmatch("([^\t]+)\t([^\n]+)\n") do
    -- The comment is the shortest code that actually starts with the current
    -- prefix, not the character's global shortest code (e.g. 或 is `he`
    -- globally but `aqoe` under `a`).
    local cand = Candidate("completion", seg.start, seg._end, text, code)
    cand.quality = 0
    yield(cand)
  end
end

return translator
